import { forwardRef, type SVGProps } from "react";

export interface IconProps extends SVGProps<SVGSVGElement> {
  size?: number | string;
}

function createMiuixIcon(
  name: string,
  vw: number,
  vh: number,
  sx: number,
  sy: number,
  tx: number,
  ty: number,
  d: string,
) {
  const Icon = forwardRef<SVGSVGElement, IconProps>(function Icon(
    { size = 24, className, width, height, style, ...props },
    ref,
  ) {
    const w = width ?? size;
    const h = height ?? size;
    const hasTransform = sx !== 1 || sy !== 1 || tx !== 0 || ty !== 0;
    const transform = hasTransform ? `translate(${tx}, ${ty}) scale(${sx}, ${sy})` : undefined;
    return (
      <svg
        ref={ref}
        width={w}
        height={h}
        viewBox={`0 0 ${vw} ${vh}`}
        fill="currentColor"
        aria-hidden="true"
        className={className}
        style={style}
        {...props}
      >
        {hasTransform ? (
          <g transform={transform}>
            <path d={d} fillRule="nonzero" />
          </g>
        ) : (
          <path d={d} fillRule="nonzero" />
        )}
      </svg>
    );
  });
  Icon.displayName = `MiuixIcon.${name}`;
  return Icon;
}

export type MiuixIconType = ReturnType<typeof createMiuixIcon>;

